import { prisma } from "../../prisma/client.js";
import { NotFoundError, ValidationError } from "../../core/errors/errors.js";

/**
 * Get the balance sheet for a specific booking.
 * Returns all ledger entries (auto-generated + manual), grouped and summed.
 */
export const getBookingBalanceSheet = async (bookingId) => {
  const booking = await prisma.booking.findUnique({ where: { id: bookingId } });
  if (!booking) throw new NotFoundError("Booking not found");

  const entries = await prisma.ledgerEntry.findMany({
    where: { bookingId },
    orderBy: { entryDate: "asc" },
  });

  const totalIncome = entries
    .filter((e) => e.type === "INCOME")
    .reduce((sum, e) => sum + Number(e.amount), 0);

  const totalExpense = entries
    .filter((e) => e.type === "EXPENSE")
    .reduce((sum, e) => sum + Number(e.amount), 0);

  return {
    bookingId,
    entries,
    summary: {
      totalIncome,
      totalExpense,
      netBalance: totalIncome - totalExpense,
    },
  };
};

/**
 * Add a custom ledger entry (manual revenue or expense) for a booking.
 * Admins can use this for offline payments, custom costs, etc.
 */
export const addCustomLedgerEntry = async (bookingId, data, adminId) => {
  const booking = await prisma.booking.findUnique({ where: { id: bookingId } });
  if (!booking) throw new NotFoundError("Booking not found");

  if (!data.type || !["INCOME", "EXPENSE"].includes(data.type)) {
    throw new ValidationError("type must be INCOME or EXPENSE");
  }
  if (!data.amount || isNaN(Number(data.amount)) || Number(data.amount) <= 0) {
    throw new ValidationError("amount must be a positive number");
  }
  if (!data.description || !String(data.description).trim()) {
    throw new ValidationError("description is required");
  }

  return prisma.ledgerEntry.create({
    data: {
      type: data.type,
      scope: "BOOKING",
      bookingId,
      source: "MANUAL",
      category: data.category || "General",
      amount: Number(data.amount),
      currency: data.currency || "INR",
      description: String(data.description).trim(),
      isAutoGenerated: false,
      entryDate: data.entryDate ? new Date(data.entryDate) : new Date(),
      createdById: adminId,
    },
  });
};

/**
 * Remove a manual ledger entry (auto-generated entries can also be removed from the
 * balance sheet view without deleting the underlying ops task).
 */
export const removeLedgerEntry = async (entryId, bookingId) => {
  const entry = await prisma.ledgerEntry.findFirst({
    where: { id: entryId, bookingId },
  });
  if (!entry) throw new NotFoundError("Ledger entry not found");

  return prisma.ledgerEntry.delete({ where: { id: entryId } });
};
